from PIL import Image
import numpy as np
a = np.array(Image.open('fig3.png'))[:,:,:3].astype(int)

def is_blue(c):
    r,g,b = c
    return (b - r > 15) and (b - g > 15) and b > 90

x0,x1 = 227, 992
bounds = {}
for x in range(x0, x1+1):
    yb = None
    for y in range(500, 28, -1):
        if is_blue(a[y,x]):
            # require 2 consecutive blue pixels upward to avoid noise
            if is_blue(a[y-1,x]) and is_blue(a[y-2,x]):
                yb = y
                break
    if yb is not None:
        bounds[x] = yb

xs = sorted(bounds)
print('columns with blue:', xs[0], xs[-1], 'count', len(xs))
# print some samples
import numpy as np
def mass(x): return 2.7906 + (x-313)/696250.0
def gval(y): return 10**(-9 - (y-27.5)/((503.5-27.5)/3))
for x in xs[::40]:
    print(x, bounds[x], f"{mass(x):.5f}", f"{gval(bounds[x]):.3e}")
# edges detail
for x in xs[:6]+xs[-6:]:
    print('edge', x, bounds[x], f"{gval(bounds[x]):.3e}")
np.save('bounds.npy', np.array([(x,bounds[x]) for x in xs]))
